parameters.jsCode:
return $input.all().map(item => {
  const data = item.json;
  return {
    json: {
      message: data.message ?? "",
      intent: data.intent ?? "",
      target_agent: data.target_agent ?? "",
      requires_customer_lookup: data.requires_customer_lookup ?? false,
      requires_order_lookup: data.requires_order_lookup ?? false,
      clarification_required: data.clarification_required ?? false,
      reason: data.reason ?? "",
      telegram_chat_id: String(data.telegram_chat_id ?? ""),
      telegram_user_id: String(data.telegram_user_id ?? ""),
      telegram_update_id: String(data.telegram_update_id ?? ""),
      correlation_id: data.correlation_id ?? null,
      execution_id: data.execution_id ?? String($execution.id),
      session_id: data.session_id ?? null,
      request_timestamp: data.request_timestamp ?? null
    }
  };
});

const update = $json ?? {};
const msg = update.message;
if (!msg) return {json:{skip:true,reason:"non_message_update"}};
if (msg.from?.is_bot) return {json:{skip:true,reason:"bot_message"}};
const message = typeof msg.text === "string" ? msg.text.trim() : "";
const chatId = msg.chat?.id;
const userId = msg.from?.id;
const messageId = msg.message_id;
if (!chatId || !userId || !messageId) return {json:{skip:true,reason:"missing_telegram_identifiers"}};
return {json:{
  message, channel:"telegram", telegram_chat_id:String(chatId), telegram_user_id:String(userId),
  telegram_username:msg.from?.username ?? null, telegram_first_name:msg.from?.first_name ?? null,
  telegram_message_id:messageId, telegram_update_id:update.update_id ?? null,
  telegram_update_key:`${chatId}:${messageId}`, language:"auto", skip:false
}};

const resumed = $input.first()?.json ?? {};
let body = resumed.body ?? resumed;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { body = {}; }
}
if (!body || typeof body !== 'object') body = {};

const original = $('Edit Fields After Supervisor').first().json;
const expectedRequestId = String(original.approval_request_id ?? '');
const receivedRequestId = String(body.approval_request_id ?? body.request_id ?? '').trim();

if (receivedRequestId && receivedRequestId !== expectedRequestId) {
  throw new Error('Approval request ID mismatch; refusing to accept this decision.');
}

const rawDecision = String(body.approval_decision ?? body.decision ?? '').trim().toUpperCase();
let outcome;
if (rawDecision === 'APPROVED' || rawDecision === 'REJECTED') {
  outcome = rawDecision;
} else if (!rawDecision) {
  // The Wait node resumed due to its configured timeout.
  outcome = 'TIMED_OUT';
} else {
  throw new Error(`Unsupported approval decision: ${rawDecision}`);
}

const response = outcome === 'APPROVED'
  ? 'Your request has been approved for the next processing step. No refund transaction has been executed automatically.'
  : outcome === 'REJECTED'
    ? 'Your request was reviewed but was not approved.'
    : 'Your approval request timed out. Please contact support.';

return [{
  json: {
    ...original,
    approval_decision: outcome,
    approval_reviewer_id: String(body.reviewer_id ?? ''),
    approval_reviewer_name: String(body.reviewer_name ?? ''),
    approval_decided_at: String(body.decided_at ?? ''),
    should_expire_record: outcome === 'TIMED_OUT',
    approval_completed: outcome === 'APPROVED' || outcome === 'REJECTED',
    response
  }
}];

const result = $json.output && typeof $json.output === 'object' ? $json.output : {};
const allowed = new Set([
  'customer_support_agent','order_support_agent','knowledge_agent',
  'human_support','clarification_required','approval_required'
]);
const requiredStrings = ['intent','target_agent','reason','approval_type','approval_reason'];
for (const key of requiredStrings) {
  if (typeof result[key] !== 'string') throw new Error(`Supervisor output field ${key} must be a string`);
}
if (!allowed.has(result.target_agent)) throw new Error('Supervisor selected an unsupported target_agent');
for (const key of ['requires_customer_lookup','requires_order_lookup','clarification_required','approval_required']) {
  if (typeof result[key] !== 'boolean') throw new Error(`Supervisor output field ${key} must be boolean`);
}
if (result.target_agent === 'approval_required') {
  if (result.approval_required !== true || !result.approval_type.trim() || !result.approval_reason.trim()) {
    throw new Error('Approval route requires approval_required=true, approval_type and approval_reason');
  }
} else if (result.approval_required === true) {
  throw new Error('approval_required must route to approval_required');
}
const routeIntent = {
  customer_support_agent: 'customer_profile_lookup',
  order_support_agent: 'order_status_lookup',
  knowledge_agent: 'knowledge_question',
  human_support: 'complaint',
  clarification_required: 'unclear_request'
};
if (routeIntent[result.target_agent] && result.intent !== routeIntent[result.target_agent]) {
  throw new Error(`Intent ${result.intent} is inconsistent with route ${result.target_agent}`);
}
if (result.target_agent === 'clarification_required' && result.clarification_required !== true) {
  throw new Error('Clarification route must set clarification_required=true');
}
if (result.target_agent === 'customer_support_agent' && result.requires_customer_lookup !== true) {
  throw new Error('Customer support route must require customer lookup');
}
if (result.target_agent === 'order_support_agent' && result.requires_order_lookup !== true) {
  throw new Error('Order support route must require order lookup');
}
return {json:{...$json,output:result,supervisor_output_valid:true}};
